function findOriginalArray(changed) {
  if (changed.length % 2 === 1) return [];
  const sorted = [...changed].sort((a, b) => a - b);
  const count = new Map();
  for (const value of sorted) {
    count.set(value, (count.get(value) ?? 0) + 1);
  }

  const original = [];
  for (const value of sorted) {
    if (count.get(value) === 0) continue;
    count.set(value, count.get(value) - 1);
    const twice = 2 * value;
    if (!count.get(twice)) return [];
    count.set(twice, count.get(twice) - 1);
    original.push(value);
  }
  return original;
}

