function findOriginalArray(changed) {
  if (changed.length % 2 === 1) return [];
  // Try every way to split the values into (x, 2x) pairs, pairing the first value with each possible partner.
  const search = rest => {
    if (rest.length === 0) return [];
    const first = rest[0];
    const tried = new Set();
    for (let j = 1; j < rest.length; j++) {
      const other = rest[j];
      if (tried.has(other)) continue;
      tried.add(other);
      if (other !== 2 * first && first !== 2 * other) continue;
      const found = search(rest.filter((_, k) => k !== 0 && k !== j));
      if (found) return [...found, Math.min(first, other)];
    }
    return null;
  };
  return search(changed) ?? [];
}

