function generate(rand, size) {
  const half = size === 'large' ? 999 : 1 + Math.floor(rand() * 5);
  const top = size === 'large' ? (rand() < 0.5 ? 50000 : 200) : 6;
  const original = Array.from({ length: half }, () => Math.floor(rand() * (top + 1)));
  const changed = [...original, ...original.map(v => 2 * v)];
  const twist = rand();
  if (twist < 0.2) changed[Math.floor(rand() * changed.length)] = Math.floor(rand() * (2 * top + 1));
  else if (twist < 0.3) changed.pop();
  else if (twist < 0.4) changed.push(Math.floor(rand() * (2 * top + 1)));
  for (let i = changed.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [changed[i], changed[j]] = [changed[j], changed[i]];
  }
  return [changed];
}
